INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'el-enigma-de-las-sombras-secretas', 'El Enigma de las Sombras Secretas', 'Dinámica de observación espejo y empatía no verbal donde los scouts siguen secretamente las posturas de su pareja hasta ser descubiertos.', '<h2>📜 Descripción de El Enigma de las Sombras Secretas</h2>
<p><b>El Enigma de las Sombras Secretas</b> es una dinámica scout de atención visual, agilidad de observación y sintonía kinesiológica. En esta actividad, los participantes se dividen en dos grupos: los <i>Modelos</i> y las <i>Sombras Secretas</i>. Antes de comenzar, cada Sombra elige en secreto y sin revelar a ningún compañero cuál Modelo va a seguir. Al sonar la música o señal de marcha, todos se desplazan libremente. Cuando la música se detiene, cada Modelo asume una postura estática creativa; al mismo tiempo, su Sombra Secreta adopta exactamente la misma postura detrás de él. El Modelo tiene un intento para girar la mirada e identificar cuál de los observadores es su sombra exacta.</p>
<p>Esta dinámica ejercita la atención a los detalles, el lenguaje no verbal y la integración en Manada, Compañía y Tropa.</p>

<h2>🎲 ¿Cómo se juega El Enigma de las Sombras Secretas?</h2>
<p>Para llevar a cabo la dinámica con precisión y entusiasmo, los dirigentes deben seguir estos pasos:</p>
<ul>
  <li><b>Asignación Secreta:</b> Los integrantes del grupo de las Sombras extraen un papelito con el nombre del Modelo al que deberán seguir en secreto durante la ronda.</li>
  <li><b>Desplazamiento Colectivo:</b> Todos los participantes trotan o caminan por el salón o campo al compás de la música o aplausos del animador.</li>
  <li><b>La Congelación de Posturas:</b> Al pausar la música, cada Modelo adopta una figura o estatua original en el lugar.</li>
  <li><b>La Réplica de la Sombra:</b> La Sombra Secreta busca rápidamente ubicarse detrás o a un costado de su Modelo asignado y replica con fidelidad milimétrica la postura corporal.</li>
  <li><b>El Descubrimiento:</b> El Modelo observa a su alrededor y señala a su Sombra. Si acierta, la pareja queda unida para la siguiente ronda de desafíos.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de El Enigma de las Sombras Secretas</h2>
<p>La actividad valora la precisión de imitación y la atención en el Tally:</p>
<ul>
  <li><b>Imitación Más Fiel:</b> Otorgar 5 puntos a la Sombra que logre la réplica postural más exacta e inmediata.</li>
  <li><b>Mayor Rapidez de Identificación:</b> Otorgar 3 puntos al Modelo que identifique a su Sombra Secreta en el primer intento.</li>
  <li><b>Sintonía de Pareja:</b> Otorgar 3 puntos a los participantes que muestren la mayor coordinación durante los desplazamientos.</li>
</ul>', '/uploads/el-enigma-de-las-sombras-secretas.webp', 'publicado', '{"areas": ["sociabilidad", "creatividad", "afectividad"], "unidades": ["manada", "compañía", "tropa"], "duracion": "20 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Salón", "Exterior", "Campo Abierto"], "materiales": ["Tarjetas de Nombres"], "objetivos": ["Estimular la atención a los detalles", "Fomentar la comunicación e interpretación", "Conocer a los demás", "Fomentar un entorno de confianza"], "justificacion_areas": "El Enigma de las Sombras Secretas potencia la sociabilidad al ejercitar el conocimiento mutuo, la atención respetuosa hacia los pares y la desinhibición social. Desarrolla la creatividad al requerir la adaptación kinésica inmediata y la réplica dramática de figuras anatómicas. Fortalece la afectividad al construir lazos de confianza y empatía no verbal dentro de la patrulla.", "variaciones": "<b>Sombras de Sonidos Scouts:</b> La Sombra no solo imita la postura sino también el sonido de animal o clave emitida por el Modelo.<br><b>Sombras de Campamento a Ciegas:</b> El Modelo realiza un nudo con piola y la Sombra debe replicar los movimientos de las manos desde atrás sin ver la tarjeta.<br><b>Mesa de Sombras Gigantes:</b> Realizar el juego con linternas potentes proyectando las sombras verdaderas contra una pared blanca.", "recomendaciones": "Fomentar un ambiente festivo y libre de presiones para que los beneficiarios disfruten la observación sin temor a fallar. Adaptar la velocidad de la música a la edad de la unidad.", "objetivos_educativos": [{"id": "b69188bf-2391-43c1-a885-abd1b13912be", "area": "Sociabilidad", "unidad": "Manada", "texto": "Acepto las reglas que se ponen en mi casa, en la escuela y en la Manada.", "como_se_cumple": "Respetando con honestidad la asignación secreta de mi pareja de juego."}, {"id": "2394dd5b-87b9-4f3d-9cdd-a42649139782", "area": "Sociabilidad", "unidad": "Manada", "texto": "Comprendo y respeto las normas que se han puesto en mi casa y en la escuela, aunque no siempre esté de acuerdo con ellas", "como_se_cumple": "Acatando las reglas de congelación de postura sin hablar durante la prueba."}, {"id": "007e85ea-2b06-48c2-8ac1-873d59643aae", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Favoreciendo el juego limpio y el respeto a la observación de cada pareja."}, {"id": "de2f5693-de4b-48f1-b870-3c62be99aea8", "area": "Sociabilidad", "unidad": "Compañía", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Promoviendo un ambiente de integración, escucha atenta y lealtad de patrulla."}, {"id": "857f21bc-db3c-4e5e-bcd5-d3d331276fad", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Conozco y respeto las principales normas de convivencia.", "como_se_cumple": "Cumpliendo con lealtad las consignas de imitación secreta."}, {"id": "bbc48d53-f4aa-4de7-84d4-95614df76034", "area": "Sociabilidad", "unidad": "Tropa", "texto": "Respeto las normas de convivencia de los distintos ambientes en que actúo, aunque no siempre esté de acuerdo con ellas.", "como_se_cumple": "Afianzando la cohesión y hermandad comunitaria en toda la Tropa."}, {"id": "ec280dd0-2d80-4b84-86ad-2d362da14886", "area": "Creatividad", "unidad": "Manada", "texto": "Me gusta participar en juegos de observación.", "como_se_cumple": "Observando con detalle las posturas de los compañeros para replicarlas con precisión."}, {"id": "dcdcce42-6b31-45f7-a135-290f0f74b5a6", "area": "Creatividad", "unidad": "Manada", "texto": "Me gustan los juegos en que tengo que usar mi agilidad mental.", "como_se_cumple": "Deduciendo con agilidad cuál de los observadores es mi Sombra Secreta."}, {"id": "e1b7276f-4fd2-4c39-a32a-bd7fadbee702", "area": "Creatividad", "unidad": "Compañía", "texto": "Doy mi opinión sobre las cosas que me pasan.", "como_se_cumple": "Expresando reflexiones sobre la experiencia de imitar e interpretar al otro."}, {"id": "0009f64a-0654-46bf-b6fc-7b9d7f278485", "area": "Creatividad", "unidad": "Compañía", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Analizando la perspectiva corporal de la Sombra desde el ángulo del Modelo."}, {"id": "49ae6ac6-be8f-4f2c-8b3e-6711d041181f", "area": "Creatividad", "unidad": "Tropa", "texto": "Doy mi opinión sobre las cosas que me pasan.", "como_se_cumple": "Aportando dinamismo e improvisación postural en cada ronda de juego."}, {"id": "3d0dff9b-11cd-4a30-b3a6-ec011ad95062", "area": "Creatividad", "unidad": "Tropa", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Sintetizando señas físicas sutiles para identificar a la pareja de imitación."}, {"id": "ab6e594f-b0a0-4e6d-96aa-7779299b02ef", "area": "Afectividad", "unidad": "Manada", "texto": "Trato con cariño a los demás en la Manada y me gusta que me traten igual.", "como_se_cumple": "Tratando con empatía y atención a mi pareja al sincronizar los movimientos."}, {"id": "c8993915-0234-464c-934e-2a09f8c4338e", "area": "Afectividad", "unidad": "Manada", "texto": "Digo lo que pienso sin ofender o insultar a mis compañeros ni burlarme de ellos.", "como_se_cumple": "Disfrutando de la imitación sin burlas y celebrando los aciertos del grupo."}, {"id": "2f8359db-221e-4a64-b2df-2b3e7b74a2db", "area": "Afectividad", "unidad": "Compañía", "texto": "Escucho las opiniones de las demás personas y si no estoy de acuerdo lo digo con respeto.", "como_se_cumple": "Escuchando con atención visual al compañero para sintonizar con su estado de ánimo."}, {"id": "672a5da0-8cab-42bb-85dd-0d1f285a1b91", "area": "Afectividad", "unidad": "Compañía", "texto": "Digo lo que pienso con respeto hacia las demás personas.", "como_se_cumple": "Comunicando impresiones con asertividad y construyendo un entorno de confianza."}, {"id": "a4060c60-7ce9-425b-bf2a-76941a689937", "area": "Afectividad", "unidad": "Tropa", "texto": "Escucho las opiniones de los demás personas y si no estoy de acuerdo lo digo con respeto.", "como_se_cumple": "Desarrollando empatía no verbal para comprender las intenciones posturales de la patrulla."}, {"id": "4ade9c82-6b0d-4a44-8bc6-2eb47a011ffb", "area": "Afectividad", "unidad": "Tropa", "texto": "Digo lo que pienso con respeto hacia los demás personas.", "como_se_cumple": "Demostrando lealtad y apoyo afectivo sincero hacia cada integrante del grupo."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

